{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C87", "C67", "C52", "C63", "C70", "C91", "C93", "C100"],
  "contradictory_card_ids": ["C36"],
  "prediction_basis_card_ids": ["C87", "C67"],
  "claims": [
    {
      "claim": "Cicaprost, a prostacyclin analog with an ether-acetic acid side chain and two hydroxyls, had a reported absolute oral bioavailability of 100% based on oral AUC0-∞ 422 pg·h/mL after 7.6 µg versus IV AUC0-∞ 409 pg·h/mL after 2.1 µg.",
      "card_ids": ["C87"]
    },
    {
      "claim": "Beraprost, a benzene-fused prostacyclin analog, showed measurable systemic exposure after a 120 µg oral dose (Cmax 84.9–240 pg/mL across subject groups), indicating oral absorption in the same structural class as the query.",
      "card_ids": ["C52", "C63", "C70", "C91", "C93", "C100"]
    },
    {
      "claim": "The L2 low prediction was based on perindoprilat (C36, 19±7% in normal volunteers), a structurally distant ACE-inhibitor diacid; the L3 prostacyclin-analog evidence is more transferable and supports F ≥ 20%.",
      "card_ids": ["C36", "C87"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C87", "C67", "C52", "C63", "C70", "C91", "C93", "C100"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "No matched oral-versus-IV study for the query.",
    "Transfer from cicaprost is moderate because the query has a benzene-fused core and saturated alpha chain versus cicaprost's bicyclic alkynyl core.",
    "Beraprost records provide Cmax only, not absolute F.",
    "Active transport or carrier-mediated absorption for this acid class is not directly demonstrated for the query.",
    "Formulation and dose effects are unknown."
  ],
  "decision_summary": "L3 adds direct oral-versus-IV exposure evidence for cicaprost (C87), a prostacyclin analog with an ether-acetic acid side chain and two hydroxyls, reporting 100% bioavailability, and oral Cmax records for beraprost, a benzene-fused prostacyclin analog. These are structurally and physicochemically much closer to the query than the perindoprilat record (C36) that drove the L2 low prediction. The new class-level evidence supports F ≥ 20%, so the prediction is flipped to high with moderate confidence."
}

